#' Merge Machine Learning Results
#'
#' @param ... One or more machine learning result objects generated by
#'   the model-specific functions.
#'
#' @return A merged list containing performance metrics, fitted models,
#'   and prediction results from all supplied machine learning models.
#' @export
#'
#' @examples
#' \dontrun{
#' result <- MergeML(
#'   RunLR(Object, gene),
#'   RunRF(Object, gene),
#'   RunSVM(Object, gene)
#' )
#' }
MergeML <- function(...) {
  model_list <- list(...)
  metrics <- c("F1","ACC","RECALL","NPV","PPV",
               "Sensitive","Specific","AUC",
               "Youden","Kappa","MODEL","SUMMARY")
  out <- setNames(vector("list", length(metrics)),metrics)
  for (metric in metrics) {
    tmp <- lapply(model_list,`[[`,metric)
    tmp <- tmp[ !vapply(tmp,is.null,logical(1))]
    tmp <- unname(tmp)
    if (length(tmp) == 0) {
      out[[metric]] <- list()
    } else {
      out[[metric]] <- do.call(c,tmp)
    }
  }
  return(out)
}
